uint64_t carrierOrder(inout Runtime s,uint slot)
{
    if(commands[s.inputBase+P_RECIPIENT_META_BASE]==0 && commands[s.inputBase+P_RECIPIENT_META_BASE+1]==0 && !alliedRandomEnabled(s)) return s.carrierRecipientOrder[slot];
